'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['createMemberDirectory']);
const { createMemberDirectory } = api;

const directory = createMemberDirectory();
assert.deepStrictEqual(Object.keys(directory), ['create', 'get', 'update', 'remove']);
assert.strictEqual(directory.get('missing'), null);
assert.strictEqual(directory.remove('missing'), false);

const input = { id: 'a', displayName: 'Ada', contact: 'ada@example.com', secret: 's1', extra: 'ignored' };
const created = directory.create(input);
assert.deepStrictEqual(created, { id: 'a', displayName: 'Ada', contact: 'ada@example.com', sequence: 1 });
assert.ok(!Object.hasOwn(created, 'secret'));
input.displayName = 'Changed';
input.secret = 'changed';
created.displayName = 'Mutated public copy';
assert.deepStrictEqual(directory.get('a'), { id: 'a', displayName: 'Ada', contact: 'ada@example.com', sequence: 1 });
assert.notStrictEqual(directory.get('a'), directory.get('a'));

assert.deepStrictEqual(directory.create({ id: 'b', displayName: 'Bob', contact: 'bob@example.com', secret: 's2' }), {
  id: 'b', displayName: 'Bob', contact: 'bob@example.com', sequence: 2
});
assert.throws(() => directory.create({ id: 'a', displayName: 'Other', contact: 'other@example.com', secret: 's' }), Error);
assert.throws(() => directory.create({ id: 'c', displayName: 'Other', contact: 'bob@example.com', secret: 's' }), Error);
assert.strictEqual(directory.get('c'), null);

for (const invalid of [null, [], 'x', {},
  { id: '', displayName: 'N', contact: 'c', secret: 's' },
  { id: 'x', displayName: '', contact: 'c', secret: 's' },
  { id: 'x', displayName: 'N', contact: '', secret: 's' },
  { id: 'x', displayName: 'N', contact: 'c', secret: '' }
]) {
  assert.throws(() => directory.create(invalid), TypeError);
}

const patch = { displayName: 'Ada Lovelace', secret: 'new-secret' };
const updated = directory.update('a', patch);
assert.deepStrictEqual(updated, { id: 'a', displayName: 'Ada Lovelace', contact: 'ada@example.com', sequence: 1 });
patch.displayName = 'Corrupted';
updated.contact = 'corrupted';
assert.deepStrictEqual(directory.get('a'), { id: 'a', displayName: 'Ada Lovelace', contact: 'ada@example.com', sequence: 1 });

assert.throws(() => directory.update('a', { contact: 'bob@example.com' }), Error);
assert.deepStrictEqual(directory.get('a'), { id: 'a', displayName: 'Ada Lovelace', contact: 'ada@example.com', sequence: 1 });
assert.throws(() => directory.update('missing', { displayName: 'X' }), Error);
for (const invalidPatch of [null, [], {}, { id: 'new' }, { displayName: '' }, { contact: 1 }, { secret: '' }, { displayName: 'X', unknown: 'y' }]) {
  assert.throws(() => directory.update('a', invalidPatch), TypeError);
}
assert.strictEqual(directory.remove('a'), true);
assert.strictEqual(directory.remove('a'), false);
assert.strictEqual(directory.get('a'), null);

